def transform(grid):
    H, W = len(grid), len(grid[0])
    output = [[0 for _ in range(2*W)] for _ in range(2*H)]

    # Helper: rotate 90° clockwise
    def rotate_90_cw(g):
        return [[g[H-1-j][i] for j in range(H)] for i in range(W)]

    # Helper: rotate 90° counter-clockwise
    def rotate_90_ccw(g):
        return [[g[j][W-1-i] for j in range(H)] for i in range(W)]

    # Helper: rotate 180°
    def rotate_180(g):
        return [[g[H-1-i][W-1-j] for j in range(W)] for i in range(H)]

    # Top-left: original
    for i in range(H):
        for j in range(W):
            output[i][j] = grid[i][j]

    # Top-right: 90° clockwise
    rotated_cw = rotate_90_cw(grid)
    for i in range(H):
        for j in range(W):
            output[i][W + j] = rotated_cw[i][j]

    # Bottom-left: 90° counter-clockwise
    rotated_ccw = rotate_90_ccw(grid)
    for i in range(H):
        for j in range(W):
            output[H + i][j] = rotated_ccw[i][j]

    # Bottom-right: 180°
    rotated_180 = rotate_180(grid)
    for i in range(H):
        for j in range(W):
            output[2*H - 1 - i][2*W - 1 - j] = rotated_180[i][j]

    return output
